<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { apiFetch } from '@/utils/api';
const mode=ref<'pre-match'|'inplay'>('pre-match'), loading=ref(false), error=ref(''), rows=ref<any[]>([]);
async function load(){loading.value=true;error.value='';try{const d=await apiFetch(`/admin/providers/odds?mode=${mode.value}`);rows.value=Array.isArray(d?.data)?d.data:[];}catch(e:any){error.value=e.message;rows.value=[]}finally{loading.value=false}}
onMounted(load); const count=computed(()=>rows.value.length)
</script>
<template><v-card elevation="0" class="border rounded-lg"><v-card-item><v-card-title>Sportmonks Odds</v-card-title><v-card-subtitle>Pre-match and in-play prices from the server-side Sportmonks feed.</v-card-subtitle><template #append><div class="d-flex ga-2"><v-select v-model="mode" :items="['pre-match','inplay']" density="compact" variant="outlined" hide-details style="width:150px" @update:model-value="load"/><v-btn variant="tonal" @click="load">Refresh</v-btn></div></template></v-card-item><v-card-text><v-alert v-if="error" type="warning" variant="tonal" class="mb-4">{{error}}</v-alert><v-chip class="mb-4" variant="tonal">{{count}} odds returned</v-chip><v-progress-linear v-if="loading" indeterminate/><v-table v-else><thead><tr><th>Fixture</th><th>Bookmaker</th><th>Market</th><th>Selection</th><th>Value</th><th>Updated</th></tr></thead><tbody><tr v-for="(o,i) in rows" :key="o.id||i"><td>{{o.fixture?.name||o.fixture_id||'—'}}</td><td>{{o.bookmaker?.name||o.bookmaker_id||'—'}}</td><td>{{o.market?.name||o.market_description||o.market_id||'—'}}</td><td>{{o.label||o.name||'—'}}</td><td>{{o.value||'—'}}</td><td>{{o.latest_bookmaker_update||o.last_update||'—'}}</td></tr><tr v-if="!rows.length&&!loading"><td colspan="6" class="text-center py-8">No odds returned for this mode or your Sportmonks plan does not include it.</td></tr></tbody></v-table></v-card-text></v-card></template>
